@using sv_8d39e82f79254e6489ebb49b7af74ecd.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Profile</h4>

    @if (isLoading)
    {
        <div class="text-muted">Loading profile…</div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible py-2">
                @statusMessage
                <button type="button" class="btn-close btn-close-sm" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="displayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="email" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="4" @bind="bio"></textarea>
                </div>
            </div>
            <div class="col-md-4">
                <div class="text-center">
                    <label class="form-label">Avatar Preview</label>
                    <div class="avatar-preview mb-2">
                        @if (!string.IsNullOrWhiteSpace(avatarUrl))
                        {
                            <img src="@avatarUrl" alt="Avatar" class="rounded-circle" style="width:120px;height:120px;object-fit:cover;" />
                        }
                        else
                        {
                            <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center"
                                 style="width:120px;height:120px;margin:0 auto;">
                                <span class="text-white fs-1">👤</span>
                            </div>
                        }
                    </div>
                    <div class="small text-muted text-break">@avatarUrl</div>
                </div>
            </div>
        </div>

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
                @(isSaving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private UserProfile? savedProfile;
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        avatarUrl = profile.AvatarUrl;
        bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new UserProfile(displayName, email, avatarUrl, bio);
            await SettingsService.SaveProfileAsync(updated);
            savedProfile = updated;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Error saving profile: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
            statusMessage = null;
        }
    }
}

@using sv_8d39e82f79254e6489ebb49b7af74ecd.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Notifications</h4>

    @if (isLoading)
    {
        <div class="text-muted">Loading notification preferences…</div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert alert-success alert-dismissible py-2">
                @statusMessage
                <button type="button" class="btn-close btn-close-sm" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <h6 class="text-muted mb-3">Notification Channels</h6>

            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h6 class="text-muted mb-3">Muted Channels</h6>
            @foreach (var channel in allChannels)
            {
                <div class="form-check mb-1">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save Preferences")
        </button>
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = [];
    private List<string> allChannels = ["general", "announcements", "engineering", "marketing", "support"];
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = [..prefs.MutedChannels];
        isLoading = false;
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        statusMessage = null;
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, [..mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        statusMessage = "Notification preferences saved!";
        isSaving = false;
    }
}

@using sv_8d39e82f79254e6489ebb49b7af74ecd.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Security</h4>

    @if (isLoading)
    {
        <div class="text-muted">Loading security settings…</div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible py-2">
                @statusMessage
                <button type="button" class="btn-close btn-close-sm" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <ChangePasswordPanel OnChangePassword="HandleChangePassword" />
        </div>

        <hr />

        <div class="mb-4">
            <h6 class="text-muted mb-3">Two-Factor Authentication</h6>
            <div class="d-flex align-items-center gap-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor" @bind="twoFactorEnabled" />
                    <label class="form-check-label" for="twoFactor">Enable 2FA</label>
                </div>
                <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <div class="small text-muted mt-2">
                    Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </div>
            }
        </div>

        <hr />

        <div class="mb-4">
            <h6 class="text-muted mb-3">Active Sessions</h6>
            <div class="table-responsive">
                <table class="table table-sm table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in sessions)
                        {
                            var isCurrent = session == sessions.FirstOrDefault();
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        @if (revokeTarget is not null)
        {
            <RevokeSessionDialog Visible="true"
                                 DeviceName="@revokeTarget.Device"
                                 OnConfirm="ConfirmRevoke"
                                 OnCancel="CancelRevoke" />
        }
    }
</div>

@code {
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = [];
    private ActiveSession? revokeTarget;
    private bool isLoading = true;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = [..settings.Sessions];
        isLoading = false;
    }

    private async Task HandleChangePassword((string current, string newPwd) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPwd);
        lastPasswordChange = DateTime.UtcNow;
    }

    private void PromptRevoke(ActiveSession session) => revokeTarget = session;
    private void CancelRevoke() => revokeTarget = null;

    private async Task ConfirmRevoke()
    {
        if (revokeTarget is null) return;
        try
        {
            await SettingsService.RevokeSessionAsync(revokeTarget.Id);
            sessions.RemoveAll(s => s.Id == revokeTarget.Id);
            statusMessage = $"Session on {revokeTarget.Device} has been revoked.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to revoke session: {ex.Message}";
            isError = true;
        }
        revokeTarget = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_8d39e82f79254e6489ebb49b7af74ecd.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (isLoading)
    {
        <div class="text-muted">Loading appearance settings…</div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert alert-success alert-dismissible py-2">
                @statusMessage
                <button type="button" class="btn-close btn-close-sm" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-6">
                <div class="mb-4">
                    <h6 class="text-muted mb-2">Theme</h6>
                    @foreach (var t in themes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                                   value="@t" checked="@(theme == t)"
                                   @onchange="() => theme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="text-muted mb-2">Font Size</h6>
                    @foreach (var fs in fontSizes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{fs}")"
                                   value="@fs" checked="@(fontSize == fs)"
                                   @onchange="() => fontSize = fs" />
                            <label class="form-check-label" for="@($"fs-{fs}")">@fs</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="text-muted mb-2">Language</h6>
                    <select class="form-select" @bind="language">
                        @foreach (var lang in languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
                    @(isSaving ? "Saving…" : "Save")
                </button>
            </div>

            <div class="col-md-6">
                <h6 class="text-muted mb-2">Live Preview</h6>
                <div class="appearance-preview p-3 border rounded @GetPreviewClasses()">
                    <div class="preview-header mb-2" style="font-size: @GetPreviewHeaderSize();">
                        Settings Dashboard
                    </div>
                    <p class="preview-text mb-2" style="font-size: @GetPreviewFontSize();">
                        This is a preview of your selected appearance settings.
                        The panel reflects your current theme, font size, and compact mode choices.
                    </p>
                    <div class="d-flex gap-2 @(compactMode ? "flex-wrap" : "")">
                        <span class="badge bg-primary">@theme Theme</span>
                        <span class="badge bg-secondary">@fontSize Font</span>
                        <span class="badge bg-info">@language</span>
                        @if (compactMode)
                        {
                            <span class="badge bg-warning text-dark">Compact</span>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;

    private static readonly string[] themes = ["Light", "Dark", "System"];
    private static readonly string[] fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;
        isLoading = false;
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        statusMessage = null;
        var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        statusMessage = "Appearance settings saved!";
        isSaving = false;
    }

    private string GetPreviewClasses()
    {
        var cls = theme switch
        {
            "Dark" => "bg-dark text-light",
            "System" => "bg-gradient",
            _ => "bg-white text-dark"
        };
        if (compactMode) cls += " py-2 px-2";
        return cls;
    }

    private string GetPreviewFontSize() => fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string GetPreviewHeaderSize() => fontSize switch
    {
        "Small" => "1.1rem",
        "Large" => "1.5rem",
        _ => "1.25rem"
