@using sv_8d39e82f79254e6489ebb49b7af74ecd.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Security</h4>

    @if (isLoading)
    {
        <div class="text-muted">Loading security settings…</div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible py-2">
                @statusMessage
                <button type="button" class="btn-close btn-close-sm" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <ChangePasswordPanel OnChangePassword="HandleChangePassword" />
        </div>

        <hr />

        <div class="mb-4">
            <h6 class="text-muted mb-3">Two-Factor Authentication</h6>
            <div class="d-flex align-items-center gap-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor" @bind="twoFactorEnabled" />
                    <label class="form-check-label" for="twoFactor">Enable 2FA</label>
                </div>
                <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <div class="small text-muted mt-2">
                    Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </div>
            }
        </div>

        <hr />

        <div class="mb-4">
            <h6 class="text-muted mb-3">Active Sessions</h6>
            <div class="table-responsive">
                <table class="table table-sm table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in sessions)
                        {
                            var isCurrent = session == sessions.FirstOrDefault();
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        @if (revokeTarget is not null)
        {
            <RevokeSessionDialog Visible="true"
                                 DeviceName="@revokeTarget.Device"
                                 OnConfirm="ConfirmRevoke"
                                 OnCancel="CancelRevoke" />
        }
    }
</div>

@code {
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = [];
    private ActiveSession? revokeTarget;
    private bool isLoading = true;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = [..settings.Sessions];
        isLoading = false;
    }

    private async Task HandleChangePassword((string current, string newPwd) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPwd);
        lastPasswordChange = DateTime.UtcNow;
    }

    private void PromptRevoke(ActiveSession session) => revokeTarget = session;
    private void CancelRevoke() => revokeTarget = null;

    private async Task ConfirmRevoke()
    {
        if (revokeTarget is null) return;
        try
        {
            await SettingsService.RevokeSessionAsync(revokeTarget.Id);
            sessions.RemoveAll(s => s.Id == revokeTarget.Id);
            statusMessage = $"Session on {revokeTarget.Device} has been revoked.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to revoke session: {ex.Message}";
            isError = true;
        }
        revokeTarget = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

