arguments.file_text:
@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-nav">
        <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="s => activeSection = s" />
    </div>
    <div class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: 80vh;
    gap: 0;
}

.settings-nav {
    width: 220px;
    flex-shrink: 0;
    border-right: 1px solid #dee2e6;
    background: #f8f9fa;
}

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    min-width: 0;
}

/* Sidebar styling */
::deep .settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0;
    padding: 0.6rem 1rem;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
    cursor: pointer;
    background: none;
    border-top: none;
    border-right: none;
    border-bottom: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

::deep .settings-sidebar .nav-link.active {
    color: #0d6efd;
    background-color: #e7f1ff;
    border-left-color: #0d6efd;
    font-weight: 600;
}

::deep .sidebar-icon {
    font-size: 1.1rem;
}

/* Section styling */
::deep .settings-section {
    max-width: 800px;
}

/* Appearance preview */
::deep .appearance-preview {
    transition: all 0.2s ease;
    min-height: 150px;
}

::deep .preview-header {
    font-weight: 600;
}

/* Revoke dialog backdrop */
::deep .modal-backdrop-custom {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    z-index: 1040;
    display: none;
}

::deep .modal-backdrop-custom.show {
    display: block;
}

::deep .modal.show {
    z-index: 1050;
}

/* Responsive */
@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-nav {
        width: 100%;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
    }

    ::deep .settings-sidebar .nav {
        flex-direction: row !important;
        overflow-x: auto;
    }

    ::deep .settings-sidebar .nav-link {
        border-left: none;
        border-bottom: 3px solid transparent;
        white-space: nowrap;
    }

    ::deep .settings-sidebar .nav-link.active {
        border-left-color: transparent;
        border-bottom-color: #0d6efd;
    }

    .settings-content {
        padding: 1rem;
    }
}

